data_model.ddl_or_schema_sketch:
-- one file: %LOCALAPPDATA%/fixflow-kb/kb.sqlite (KB_HOME overrides); runtime asserts sqlite_version() >= 3.51.3
PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000; PRAGMA foreign_keys=ON;
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL); -- schema_version, min_cli_version, store_id, thresholds JSON, recipe_version
CREATE TABLE root_cause(id TEXT PRIMARY KEY, statement TEXT NOT NULL, family TEXT, created_event TEXT NOT NULL);
CREATE TABLE check_spec(
  id TEXT PRIMARY KEY,                       -- sha256(canonical spec JSON)
  kind TEXT NOT NULL CHECK(kind IN('structural_probe','library_probe','test_id','scripted')),
  spec JSON NOT NULL,                        -- paths, pattern, anchor, test ids, image, timeout
  polarity TEXT NOT NULL CHECK(polarity IN('signal_means_present','absence_means_present','test_fail_means_present','protective_must_pass')),
  control TEXT NOT NULL CHECK(control IN('historical','synthetic','none')),
  fails_at TEXT, passes_at TEXT,             -- mainline SHAs, or 'fixture:<sha256>' / 'mutant:<sha256>' blobs
  approved_by TEXT, approved_spec_sha TEXT); -- scripted only; approver != author
CREATE TABLE entry(
  id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN('defect','trap','do_not_apply','invariant_rationale')),
  status TEXT NOT NULL CHECK(status IN('wip','not_validated','unverified_seed','validated','known_error_open','conflict','archived','withdrawn','superseded')),
  title TEXT NOT NULL, root_cause_id TEXT REFERENCES root_cause(id), current_rev TEXT NOT NULL,
  check_id TEXT REFERENCES check_spec(id), author JSON NOT NULL,
  version INTEGER NOT NULL DEFAULT 1, last_seq INTEGER NOT NULL);  -- folded header; CAS on version
CREATE TABLE entry_rev(id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entry(id), prev_rev TEXT REFERENCES entry_rev(id),
  schema_version INTEGER NOT NULL, body JSON NOT NULL); -- manifestation_conditions, applies_while, diagnosis_path, fix_permanent, workaround, fix_commits, cost_evidence, doc_pointers
CREATE TABLE negative_result(id TEXT PRIMARY KEY, entry_rev TEXT NOT NULL REFERENCES entry_rev(id), approach TEXT NOT NULL, why_failed TEXT NOT NULL,
  failure_class TEXT NOT NULL CHECK(failure_class IN('wrong_premise','incomplete','worse_side_effect','false_proof','not_reproducible','env_specific')),
  proof TEXT NOT NULL CHECK(proof IN('executed','argued','reported')), scope_digest TEXT, evidence_ref TEXT);
CREATE TABLE handle(id INTEGER PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES entry(id), type TEXT NOT NULL,
  raw_scrubbed TEXT NOT NULL, canonical TEXT NOT NULL, canonical_hash TEXT NOT NULL, recipe_version INTEGER NOT NULL,
  state TEXT NOT NULL CHECK(state IN('active','proposed','retired')), source_event TEXT NOT NULL, UNIQUE(entry_id,type,canonical_hash));
CREATE TABLE footprint_item(entry_id TEXT NOT NULL REFERENCES entry(id),
  kind TEXT NOT NULL CHECK(kind IN('file','symbol','config_key','dependency','env','remote_resolver')),
  locator TEXT NOT NULL, hash TEXT, verified_sha TEXT NOT NULL,
  tier TEXT NOT NULL CHECK(tier IN('causal','declared','cognitive','env_probe')), PRIMARY KEY(entry_id,kind,locator));
CREATE TABLE entry_event(
  seq INTEGER PRIMARY KEY AUTOINCREMENT,      -- local order only
  id TEXT NOT NULL UNIQUE,                    -- sha256(canonical JSON): idempotency + journal file name
  entry_id TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN('recorded','control_verified','reviewed_confirmed','confirmed','refuted','suspect','reaffirmed','invalidated','revised','superseded','withdrawn','archived','handle_proposed','handle_accepted','discriminator_proposed','discriminator_accepted','incident_linked')),
  at TEXT NOT NULL, actor JSON NOT NULL, code_sha TEXT, on_mainline INTEGER, footprint_digest TEXT,
  verdict TEXT CHECK(verdict IN('applies','not_applies','inconclusive')), evidence JSON, payload JSON);
CREATE INDEX ev_entry ON entry_event(entry_id, seq);
CREATE TABLE incident_link(entry_rev TEXT NOT NULL, ref TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('resolved','referenced','refuted','co_occurred')), event_id TEXT NOT NULL, PRIMARY KEY(entry_rev,ref,kind));
CREATE TABLE lineage_edge(src TEXT NOT NULL, dst TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('supersedes','revision_of','sibling_of')), PRIMARY KEY(src,dst,kind));
CREATE TABLE lookup(id TEXT PRIMARY KEY, at TEXT NOT NULL, actor JSON NOT NULL, code_sha TEXT, tool TEXT, phase TEXT,
  query_scrubbed TEXT NOT NULL, canonical JSON NOT NULL, recipe_version INTEGER NOT NULL, engine TEXT NOT NULL, index_lag INTEGER NOT NULL,
  result TEXT NOT NULL CHECK(result IN('miss','candidate','lead')), shown JSON, features JSON, depth INTEGER,
  tokens_in INTEGER, tokens_out INTEGER, wall_ms INTEGER,   -- NULL = unknown, never 0
  outcome TEXT CHECK(outcome IN('applies','not_applies','inconclusive','missed_existing')), outcome_event TEXT);
CREATE TABLE claim(claim_seq INTEGER PRIMARY KEY AUTOINCREMENT, signature TEXT NOT NULL, holder JSON NOT NULL, at TEXT NOT NULL,
  lease_until TEXT, released_at TEXT, entry_id TEXT);      -- lease policy deferred (KS-R5)
CREATE UNIQUE INDEX one_open_claim ON claim(signature) WHERE released_at IS NULL;
-- SEARCH ROLE: projections, written only by the projector, rebuildable from entry_event
CREATE TABLE projection_state(name TEXT PRIMARY KEY, engine TEXT NOT NULL, recipe_version INTEGER NOT NULL, last_seq INTEGER NOT NULL, built_at TEXT NOT NULL, content_hash TEXT);
CREATE TABLE exact_handle(type TEXT NOT NULL, canonical_hash TEXT NOT NULL, entry_id TEXT NOT NULL, PRIMARY KEY(type,canonical_hash,entry_id)) WITHOUT ROWID;
CREATE TABLE search_doc(rowid INTEGER PRIMARY KEY, entry_id TEXT NOT NULL UNIQUE, title TEXT, templates TEXT, signatures TEXT, symptoms TEXT, anchors TEXT, diagnosis TEXT, ruled_out TEXT, facets JSON);
CREATE VIRTUAL TABLE search_fts USING fts5(title, templates, signatures, symptoms, anchors, diagnosis, ruled_out, content='search_doc', content_rowid='rowid', tokenize='porter unicode61');
CREATE VIRTUAL TABLE search_tri USING fts5(templates, symptoms, content='search_doc', content_rowid='rowid', tokenize='trigram');
CREATE VIRTUAL TABLE search_vocab USING fts5vocab(search_fts, 'row');   -- df(term), N for IDF coverage
CREATE TABLE validity(entry_id TEXT NOT NULL, code_sha TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('valid','suspect','stale','unknown')), reason JSON, computed_at TEXT NOT NULL, PRIMARY KEY(entry_id,code_sha)); -- cache of a recomputable query
-- ANALYTICS ROLE: views in the same engine (KS-R6)
CREATE VIEW v_entry_outcomes AS SELECT entry_id, sum(type='confirmed') confirmed, sum(type='refuted') refuted, sum(type='reaffirmed') reaffirmed, sum(type='invalidated') invalidated, max(at) last_event FROM entry_event GROUP BY entry_id;
CREATE VIEW v_lead_precision AS SELECT count(*) leads, sum(outcome='applies') applied, sum(outcome='not_applies') false_leads, sum(outcome IS NULL OR outcome='inconclusive') unresolved FROM lookup WHERE result='lead';
CREATE VIEW v_missed_existing AS SELECT * FROM lookup WHERE outcome='missed_existing';
CREATE VIEW v_supersede_closure AS WITH RECURSIVE up(src,dst) AS (SELECT src,dst FROM lineage_edge WHERE kind='supersedes' UNION SELECT u.src,e.dst FROM up u JOIN lineage_edge e ON e.src=u.dst AND e.kind='supersedes') SELECT * FROM up;  -- no depth column in the UNION key (20x slower, E-08.f16)
-- entries citing changed files: SELECT DISTINCT entry_id FROM footprint_item WHERE kind='file' AND locator IN (<git diff --name-only>);
-- failed approaches for similar symptoms: lookup candidates JOIN entry USING root_cause_id JOIN entry_rev JOIN negative_result.
